// GENERATED by `pnpm --filter @armada/desktop codegen`. Do not hand-edit.
//
// Every act Bridge offers: what it is called, what it is bound to, and the
// glyph it draws — or why it draws none. From
// `crates/core-model/domain/actions.toml`, which is the artifact
// `docs/contracts/design-system.md` promises under "One artifact, three
// columns" and the authority on all three.
//
// **A Motion is here and is not an act.** `move_focus` and `open_focused`
// move the cursor and act on nothing; the registry says they
// appear in no palette and carry no glyph, so they are emitted for
// completeness and filtered out by anything that draws a list of acts.
//
// **A blank glyph is a fact, not a default.** `iconAbsent` says which kind of
// blank it is: `undecided` means no registered silhouette means the act and
// assigning one is a decision for `packages/icons/icons/`; `by design`
// means a document decided the act carries none. A surface says which it is
// drawing rather than inventing a glyph to fill the column.
//
// **`unbuilt` names the issue that answers the key.** The registry is ahead
// of the app deliberately, because the map was settled by drawing. A palette
// that displays a binding beside every entry would otherwise offer a row a
// person presses and gets nothing from, which is worse than one that is
// absent.

import { ChartNoAxesGantt, ChevronLeft, File, Link, Lock, Maximize2, MessageSquare, Plus, Settings, Shapes, StickyNote, VectorSquare, X, Zap } from "lucide-react";
import type { LucideIcon } from "lucide-react";

/** Whether the row is an act or a movement of the cursor. */
export type ActionKind = "Action" | "Motion";

/** Modifier-based and working anywhere, or single-key and on what is focused. */
export type ActionTier = "Global" | "Contextual";

/**
 * Where the binding is offered. The registry's own set, spelled the registry's
 * way, and read off the rows rather than declared — so a scope that appears
 * in `actions.toml` appears here and nowhere else has to be told.
 */
export type ActionScope =
  | "anywhere"
  | "call"
  | "dashboard"
  | "deck"
  | "issues"
  | "list"
  | "list and detail"
  | "logbook"
  | "open studio"
  | "plan"
  | "projects"
  | "review";

/** Why an act's glyph column is empty. `null` where it is not. */
export type IconAbsence = "undecided" | "by design";

export type Action = {
  /** The id an implementation binds to. The registry's table key. */
  readonly id: string;
  readonly kind: ActionKind;
  readonly tier: ActionTier;
  /** What a person reads, in the lexicon's word. Never the id. */
  readonly verb: string;
  /** The glyph, or `null` — in which case `iconAbsent` says why. */
  readonly icon: LucideIcon | null;
  readonly iconAbsent: IconAbsence | null;
  /** The binding, spelled as the contract's map spells it. */
  readonly shortcut: string;
  readonly scope: ActionScope;
  readonly destructive: boolean;
  readonly confirms: boolean;
  /** The issue that gives the binding an act, on a row nothing answers yet. */
  readonly unbuilt: string | null;
};

