/**
 * One act, by the id an implementation binds to.
 *
 * `| undefined` because a caller may ask for an id this build has never
 * heard of, and a missing act is a real answer rather than a crash.
 */
export const ACTION: Readonly<Record<string, Action | undefined>> = Object.fromEntries(
  ACTIONS.map((action) => [action.id, action]),
);
